import {normalizeName,compareName,bestMatch,scanText,band} from './match.js';
const BASE='/IWT-Open-Sanctions/'; let db={entities:[],cases:[],sources:[],relationships:[],metadata:{}}; const root=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const status=s=>`<span class="status s-${esc(s).replace(/[^a-z]/gi,'').toLowerCase()}">${esc(s)}</span>`; const hash=(p)=>`#${p}`;
async function load(){const names=['entities','cases','sources','relationships','metadata'];const vals=await Promise.all(names.map(n=>fetch(`data/${n}.json`).then(r=>r.json())));names.forEach((n,i)=>db[n]=vals[i]);route()}
function shell(body){root.innerHTML=`<header><a class="brand" href="#/"><span class="mark">IWT</span><span>IWT Open Sanctions<small>WILDLIFE TRADE INTELLIGENCE</small></span></a><button id="menu" aria-label="Toggle navigation">☰</button><nav><a href="#/search">Search</a><a href="#/check">Document check</a><a href="#/bulk">Bulk check</a><a href="#/downloads">Data</a><a href="#/about">Methodology</a><a href="#/contribute">Contribute</a></nav></header><div class="disclaimer">Independent OSINT project · Inclusion does not establish criminal guilt · Always review cited sources</div><main>${body}</main><footer><b>IWT Open Sanctions</b><span>Free, open and privacy-preserving investigative aid. Not affiliated with OpenSanctions.</span><span>Data is not legally authoritative.</span></footer>`;document.querySelector('#menu').onclick=()=>document.querySelector('nav').classList.toggle('open')}
function home(){const es=db.entities,c=new Set(es.flatMap(e=>e.countries));const count=t=>es.filter(e=>e.entity_type===t).length;const st=s=>es.filter(e=>e.status_summary===s).length;shell(`<section class="hero"><div class="eyebrow">PUBLIC-INTEREST OSINT · STATIC · SOURCE-AUDITABLE</div><h1>Names hide in paperwork.<br><em>Connections shouldn't.</em></h1><p>Open-source intelligence on people and entities reported in connection with illegal wildlife trade — built for careful, evidence-led screening.</p><form id="hero-search"><input id="hq" aria-label="Search name" placeholder="Search a name, alias, company, country or species…"><button>Search database →</button></form><div class="privacy">⌁ No accounts · No tracking · Search stays in your browser</div></section><section class="actions"><a href="#/search"><b>01</b><h2>Search Database</h2><p>Resolve names and aliases across public enforcement reporting.</p><span>Begin search →</span></a><a href="#/check"><b>02</b><h2>Check a Document</h2><p>Screen manifests, permits and records locally in your browser.</p><span>Check locally →</span></a><a href="#/contribute"><b>03</b><h2>Contribute Intelligence</h2><p>Propose a public-source candidate for human review.</p><span>Review workflow →</span></a></section><section class="stats"><h2>Database coverage</h2><div>${[['Entities',es.length],['People',count('Person')],['Businesses & facilities',count('Business')+count('Facility')],['Countries',c.size],['Cases / events',db.cases.length],['Public sources',db.sources.length],['Convicted / sentenced',st('Convicted / Sentenced')],['Charged / indicted',st('Charged / Indicted')]].map(x=>`<article><strong>${x[1]}</strong><span>${x[0]}</span></article>`).join('')}</div><p>Dataset v${db.metadata.data_version} · Updated ${db.metadata.generated_date} · Figures generated from current data.</p></section>`);document.querySelector('#hero-search').onsubmit=e=>{e.preventDefault();location.hash='/search?q='+encodeURIComponent(document.querySelector('#hq').value)}}
function searchPage(){const q=new URLSearchParams(location.hash.split('?')[1]||'').get('q')||'';const opts=(field)=>[...new Set(db.entities.flatMap(e=>Array.isArray(e[field])?e[field]:[e[field]]))].filter(Boolean).sort().map(x=>`<option>${esc(x)}</option>`).join('');shell(`<section class="pagehead"><div class="eyebrow">ENTITY INDEX</div><h1>Search database</h1><p>Search names, aliases, jurisdictions, roles, cases and commodities. Fuzzy results are leads, not identity confirmation.</p></section><section class="searchpanel"><input id="q" value="${esc(q)}" placeholder="Name, alias, network, species…" aria-label="Search database"><div class="filters"><select id="type"><option value="">All entity types</option>${opts('entity_type')}</select><select id="country"><option value="">All countries</option>${opts('countries')}</select><select id="region"><option value="">All regions</option>${opts('regions')}</select><select id="stat"><option value="">All statuses</option>${opts('status_summary')}</select><select id="species"><option value="">All commodities</option>${opts('species_or_commodities')}</select><select id="year"><option value="">All years</option>${[...new Set(db.cases.map(c=>c.year))].sort().map(x=>`<option>${x}</option>`).join('')}</select><select id="sourceType"><option value="">All source types</option>${[...new Set(db.sources.map(s=>s.source_type))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="confidence"><option value="">All confidence</option>${[...new Set(db.sources.map(s=>s.confidence))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select><button id="clear" class="ghost">Clear filters</button></div></section><div id="results"></div>`);
 const render=()=>{let query=document.querySelector('#q').value;let rows=db.entities.map(e=>{const searchable=[e.canonical_name,...e.aliases,...e.countries,...e.roles,...e.species_or_commodities,...e.case_ids.map(id=>db.cases.find(c=>c.case_id===id)?.network_or_case_name||'')];let score=query?Math.max(...searchable.map(x=>compareName(query,x).score),normalizeName(searchable.join(' ')).includes(normalizeName(query))?92:0):100;return {e,score}}).filter(x=>x.score>=50);const val=id=>document.querySelector(id).value;rows=rows.filter(({e})=>(!val('#type')||e.entity_type===val('#type'))&&(!val('#country')||e.countries.includes(val('#country')))&&(!val('#region')||e.regions.includes(val('#region')))&&(!val('#stat')||e.status_summary===val('#stat'))&&(!val('#species')||e.species_or_commodities.includes(val('#species')))&&(!val('#year')||e.case_ids.some(id=>db.cases.find(c=>c.case_id===id)?.year===val('#year')))&&(!val('#sourceType')||e.source_ids.some(id=>db.sources.find(s=>s.source_id===id)?.source_type===val('#sourceType')))&&(!val('#confidence')||e.source_ids.some(id=>db.sources.find(s=>s.source_id===id)?.confidence===val('#confidence')))).sort((a,b)=>b.score-a.score);document.querySelector('#results').innerHTML=`<div class="resultcount"><b>${rows.length}</b> matching entities</div><div class="cards">${rows.map(({e,score})=>`<a class="entity" href="#/entity/${e.entity_id}"><div><span class="type">${esc(e.entity_type)} · ${esc(e.entity_id)}</span><h3>${esc(e.canonical_name)}</h3>${e.aliases.length?`<p>Also known as: ${esc(e.aliases.join(', '))}</p>`:''}</div><div>${status(e.status_summary)}<p>${esc(e.countries.join(' · '))}</p>${query?`<small>${score}% search relevance</small>`:''}</div></a>`).join('')}</div>`};document.querySelectorAll('input,select').forEach(x=>x.oninput=render);document.querySelector('#clear').onclick=()=>{document.querySelectorAll('select').forEach(x=>x.value='');document.querySelector('#q').value='';render()};render()}
function entity(id){const e=db.entities.find(x=>x.entity_id===id);if(!e)return notFound();const cases=e.case_ids.map(id=>db.cases.find(c=>c.case_id===id)).filter(Boolean).sort((a,b)=>b.date.localeCompare(a.date));const sources=e.source_ids.map(id=>db.sources.find(s=>s.source_id===id)).filter(Boolean);shell(`<a class="back" href="#/search">← Back to search</a><section class="profile"><div><span class="type">${esc(e.entity_type)} · ${esc(e.entity_id)}</span><h1>${esc(e.canonical_name)}</h1>${status(e.status_summary)}</div><div class="notice"><b>Legal status warning</b> Inclusion does not establish criminal guilt. Status is reproduced from cited public sources. Review sources before operational or legal decisions.</div><dl><dt>Aliases</dt><dd>${esc(e.aliases.join(', ')||'None recorded')}</dd><dt>Countries / jurisdictions</dt><dd>${esc(e.countries.join(', '))}</dd><dt>Regions</dt><dd>${esc(e.regions.join(', '))}</dd><dt>Roles / connections</dt><dd>${esc(e.roles.join(', '))}</dd><dt>Species / commodities</dt><dd>${esc(e.species_or_commodities.join(', '))}</dd></dl></section><section class="section"><h2>Cases / events <small>${cases.length}</small></h2>${cases.map(c=>`<article class="event"><time>${esc(c.date)}</time><div>${status(c.status)}<h3>${esc(c.network_or_case_name||'Reported event')}</h3><p>${esc(c.description)}</p><dl><dt>Jurisdiction</dt><dd>${esc(c.jurisdiction)}</dd><dt>Status detail</dt><dd>${esc(c.status_detail)}</dd><dt>Outcome</dt><dd>${esc(c.outcome||'Not reported')}</dd></dl></div></article>`).join('')}</section><section class="section"><h2>Sources <small>${sources.length}</small></h2>${sources.map(s=>`<article class="source"><div><span>${esc(s.source_type)} · ${esc(s.language)} · ${esc(s.confidence)} confidence</span><h3>${esc(s.publisher)}</h3><p>${esc(s.title)}</p><time>${esc(s.publication_date)}</time></div><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a></article>`).join('')}</section><section class="section"><h2>Relationships</h2><p>${e.relationship_ids.length?'See source-backed relationships below.':'No structured relationships recorded in V1. Relationships are never inferred from proximity alone.'}</p></section><section class="notice"><b>Caveats</b>${esc(e.caveats.join(' ')||'No additional record-specific caveat supplied. Global legal caution still applies.')}</section>`)}
function checker(){shell(`<section class="pagehead"><div class="eyebrow">LOCAL DOCUMENT INTELLIGENCE</div><h1>Check a document</h1><p>Paste text or select TXT, CSV, TSV, text-based PDF, or an image. Processing stays on this device.</p></section><div class="privacybox"><b>🔒 Your document never leaves this browser.</b> It is not uploaded, stored, analyzed or tracked by IWT Open Sanctions.</div><section class="checkgrid"><div><label for="doc">Document text</label><textarea id="doc" rows="14" placeholder="Paste a manifest, permit, invoice or company record…"></textarea><label class="upload">Choose local file <input id="file" type="file" accept=".txt,.csv,.tsv,.pdf,image/*"></label><button id="run">Check for entity names</button><p id="progress"></p></div><aside><h3>How matching works</h3><ol><li>Exact canonical and alias detection</li><li>Unicode and punctuation normalization</li><li>Company suffix normalization</li><li>Human review of every lead</li></ol><p>PDF extraction uses a conservative local text decoder in this dependency-free build. Scanned PDFs require conversion to an image. Image OCR is not bundled in V1.</p></aside></section><div id="matches"></div>`);const file=document.querySelector('#file');file.onchange=async()=>{const f=file.files[0];if(!f)return;document.querySelector('#progress').textContent='Reading locally…';if(f.type.startsWith('image/')){document.querySelector('#progress').textContent='Image OCR is not included in this stable V1 build; paste OCR text or use a text-based PDF.';return}const buf=await f.arrayBuffer();let text;if(f.type==='application/pdf'||f.name.endsWith('.pdf')){const raw=new TextDecoder('latin1').decode(buf);text=[...raw.matchAll(/\(([^()]*)\)\s*Tj/g)].map(x=>x[1]).join(' ')}else text=new TextDecoder().decode(buf);document.querySelector('#doc').value=text;document.querySelector('#progress').textContent=`Read ${f.name} locally (${text.length} text characters).`};document.querySelector('#run').onclick=()=>{const matches=scanText(document.querySelector('#doc').value,db.entities);document.querySelector('#matches').innerHTML=`<section class="section"><h2>${matches.length} potential matches</h2><div class="notice">A potential name match is an investigative lead, not identity confirmation. Verify identifiers, jurisdiction, addresses and sources. No match does not clear a person or entity.</div>${matches.map(m=>matchCard(m,m.matched)).join('')}</section>`}}
function matchCard(m,input){return `<article class="match"><div><span class="score">${m.score}% · ${band(m.score)}</span><h3>${esc(input)} → ${esc(m.entity.canonical_name)}</h3><p>${esc(m.reason)}${m.alias?' · Alias involved':''}</p><small>${esc(m.entity.entity_id)} · ${esc(m.entity.entity_type)} · ${esc(m.entity.countries.join(', '))}</small><br>${status(m.entity.status_summary)}</div><a href="#/entity/${m.entity.entity_id}">Full profile →</a></article>`}
function bulk(){shell(`<section class="pagehead"><div class="eyebrow">BULK SCREENING</div><h1>Bulk name check</h1><p>Enter one name per line or upload a CSV/TXT. Matching and export happen locally.</p></section><textarea id="bulk" rows="12" placeholder="Company A\nJohn Smith\nBION TERRARIUM CENTER LLC"></textarea><div class="row"><input id="bulkfile" type="file" accept=".csv,.txt"><button id="bulkrun">Check names</button><button id="export" class="ghost" disabled>Export CSV</button></div><div id="bulkout"></div>`);let results=[];document.querySelector('#bulkfile').onchange=async e=>document.querySelector('#bulk').value=await e.target.files[0].text();document.querySelector('#bulkrun').onclick=()=>{const names=document.querySelector('#bulk').value.split(/[\n,;]+/).map(x=>x.trim()).filter(Boolean);results=names.map(name=>({name,match:bestMatch(name,db.entities)}));const exact=results.filter(x=>x.match.score>=90).length,possible=results.filter(x=>x.match.score>=75&&x.match.score<90).length;document.querySelector('#bulkout').innerHTML=`<div class="summary"><b>${names.length} checked</b><span>${exact} exact/high</span><span>${possible} possible</span><span>${names.length-exact-possible} no match</span></div>${results.map(x=>x.match.score>=60?matchCard(x.match,x.name):`<article class="match"><div><h3>${esc(x.name)}</h3><p>No credible match</p></div></article>`).join('')}`;document.querySelector('#export').disabled=false};document.querySelector('#export').onclick=()=>{const q=s=>'"'+String(s).replaceAll('"','""')+'"';const csv='input,band,score,entity_id,canonical_name,reason\n'+results.map(x=>[x.name,band(x.match.score),x.match.score,x.match.score>=60?x.match.entity.entity_id:'',x.match.score>=60?x.match.entity.canonical_name:'',x.match.reason].map(q).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='iwt-bulk-check.csv';a.click();URL.revokeObjectURL(a.href)}}
function downloads(){const files=['entities.json','entities.csv','sources.json','sources.csv','cases.json','relationships.json','relationships.csv','complete.json','metadata.json'];shell(`<section class="pagehead"><div class="eyebrow">OPEN DATA</div><h1>Download the dataset</h1><p>Static, key-free research files. Dataset licensing remains for the repository owner to determine; source copyrights remain with publishers.</p></section><div class="downloads">${files.map(f=>`<a href="data/${f}" download><b>${f}</b><span>Download ↘</span></a>`).join('')}</div><section class="notice"><b>Data notice</b> Version ${db.metadata.data_version} · schema ${db.metadata.schema_version} · generated ${db.metadata.generated_date}. This index is not legally authoritative; verify every record against cited sources.</section>`)}
function about(){shell(`<section class="pagehead"><div class="eyebrow">ABOUT & METHODOLOGY</div><h1>Evidence before inference.</h1><p>An independent open-source index of people and entities appearing in public illegal wildlife trade reporting.</p></section><div class="prose"><h2>Purpose</h2><p>IWT Open Sanctions helps investigators find prior public reporting, not automate accusations or establish guilt.</p><h2>Source hierarchy</h2><ol><li>Courts, prosecutors and official enforcement material</li><li>Government releases</li><li>Major media</li><li>Reputable investigative NGOs</li><li>Other credible OSINT sources</li></ol><h2>Legal status</h2><p>Conviction, guilty plea, charge, arrest, investigation, wanted status and connected-entity status remain distinct. A later case outcome should be recorded as a new event or reviewed update.</p><h2>Limitations</h2><ul><li>Inclusion is not proof of guilt.</li><li>Coverage is incomplete; many cases never name subjects publicly.</li><li>Absence is not evidence of legitimacy or clearance.</li><li>Fuzzy matches require human verification.</li><li>Sources can change, disappear or later be corrected.</li></ul><h2>Corrections</h2><p>Open a correction issue with the entity ID, specific concern, and authoritative supporting sources. Maintainers follow the documented removal and correction process.</p><h2>Privacy</h2><p>Searches and document checks run entirely client-side. There is no analytics, account, backend, query logging, or document transmission.</p></div>`)}
function contribute(){shell(`<section class="pagehead"><div class="eyebrow">HUMAN-REVIEWED CONTRIBUTIONS</div><h1>Contribute intelligence</h1><p>Propose a candidate based on a public source. Nothing submitted is automatically added to the database.</p></section><div class="notice warning"><b>Public submission warning</b> GitHub Issues are publicly visible before moderation. Do not submit unnecessary private personal data, confidential information or unsupported allegations.</div><div class="workflow">${['Candidate issue','Evidence review','Duplicate & alias check','Legal status review','Approve or reject','Curated merge & rebuild'].map((x,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b><span>${x}</span></div>`).join('')}</div><a class="button" href="https://github.com/Coffee-Sentinal/IWT-Open-Sanctions/issues/new?template=candidate-record.yml" target="_blank" rel="noopener">Open public candidate form ↗</a><p class="muted">Submitting does not imply endorsement or acceptance. See CONTRIBUTING.md and docs/MODERATION.md.</p>`)}
function notFound(){shell('<section class="pagehead"><h1>Page not found</h1><a href="#/">Return home</a></section>')}
function route(){scrollTo(0,0);const p=location.hash.slice(1)||'/';if(p==='/')home();else if(p.startsWith('/search'))searchPage();else if(p.startsWith('/entity/'))entity(decodeURIComponent(p.split('/')[2]));else if(p==='/check')checker();else if(p==='/bulk')bulk();else if(p==='/downloads')downloads();else if(p==='/about')about();else if(p==='/contribute')contribute();else notFound()}
addEventListener('hashchange',route);load().catch(e=>{root.textContent='Unable to load database: '+e.message});
